package rex

import (
	"fmt"
	"regexp"
	"strings"
)

// maxHubLabel is the longest hub label RenderPalette takes. Rex sets no limit
// we have read; 64 bytes is the plan's bound (T17.11), long enough for any
// host label a person types and short enough to keep the log lines readable.
const maxHubLabel = 64

// hubLabel is the shape of a hub label RenderPalette takes. Besides being a
// sane host label, it is what makes the generated file safe: the label is
// written between double quotes in Lua, and this pattern admits no quote,
// backslash, newline or other byte that could end the string or start code,
// so no escaping is needed and none is attempted.
var hubLabel = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

// RenderPalette returns afk.lua, the Lua file `afk rex setup` puts beside the
// laptop's Rex init.lua. It defines four palette actions that act on the hub,
// the Rex host named hub in the laptop's `rex hosts` list: open the control
// room, go to the next agent that needs the owner, and pause or resume the
// build.
//
// It is pure, so the file can be table-tested and parsed without Rex or a
// laptop. Custom actions belong to the client (T17.11's background): this
// file runs on the laptop, and every call in it goes to the hub through
// rex.server(HUB), never to the laptop's own server.
//
// The Lua uses only what was pinned against the real rex CLI (docs/decisions.md
// ## T17.11): rex.server(label) throws for a label the device does not know,
// and the helper it returns is called with a dot, server.call(method, args),
// which returns nil and an error text for a failed call instead of throwing.
// So the file wraps both in pcall and turns every failure into one rex.log
// line naming the hub, and an unknown label never raises an error in the
// owner's palette. One more shape was pinned while building this file
// against a scratch Rex server, and is recorded in the T17.11 notepad: the hub
// refuses session.list_blocks, block.method, session.focus_window and
// session.new_window with "stream is not attached to session" (the same
// calls made with `rex api call` from a shell are not refused, which is why
// the W1 evidence does not show it) until the connection sends
// session.attach, so the Lua attaches on that refusal only and detaches
// afterwards.
//
// No key is bound: rex.bind appears only in comments, because the owner's
// keys are theirs to choose and a bound key could shadow one they already use.
func RenderPalette(hub string) ([]byte, error) {
	if err := checkHubLabel(hub); err != nil {
		return nil, err
	}
	var b strings.Builder
	b.WriteString(paletteHeader)
	fmt.Fprintf(&b, "-- The Rex host these actions act on, as `rex hosts` on this device lists it.\nlocal HUB = \"%s\"\n", hub)
	b.WriteString(paletteBody)
	return []byte(b.String()), nil
}

// checkHubLabel says in plain words why a hub label cannot be used.
func checkHubLabel(hub string) error {
	switch {
	case hub == "":
		return fmt.Errorf("the hub label is empty; give the label of the Rex host afk runs on, as `rex hosts` lists it (for example vm)")
	case len(hub) > maxHubLabel:
		return fmt.Errorf("the hub label is %d bytes long; it can be at most %d", len(hub), maxHubLabel)
	case !hubLabel.MatchString(hub):
		return fmt.Errorf("the hub label %q cannot be used: it must start with a letter or digit and hold only letters, digits, dots, dashes and underscores", hub)
	}
	return nil
}

// paletteHeader opens the file. The rex.bind lines are suggestions inside
// comments on purpose; see RenderPalette.
const paletteHeader = `-- afk.lua: afk's actions in the Rex palette.
--
-- Generated by ` + "`afk rex setup`" + `. Do not edit this file by hand: running
-- ` + "`afk rex setup`" + ` again writes it from scratch and any change here is lost.
-- To act on a different Rex host, run ` + "`afk rex setup --hub LABEL`" + ` again.
--
-- Your init.lua loads it with:
--   require("afk")
--
-- The actions are in the palette under "afk". No key is bound. To put an
-- action on a key, copy its line into your init.lua without the leading "-- ":
-- rex.bind("ctrl+alt+a", "afk_control_room")
-- rex.bind("ctrl+alt+n", "afk_next_needs_you")
-- rex.bind("ctrl+alt+p", "afk_pause")
-- rex.bind("ctrl+alt+r", "afk_resume")

`

// paletteBody is everything after the HUB constant. The call shapes are the
// ones recorded in docs/decisions.md ## T17.11; the comments in the Lua say why
// for the owner, who may read this file.
const paletteBody = `
-- The Rex session the afk daemon keeps the control room in. The control
-- room's window and its terminal carry the same label.
local CONTROL_ROOM = "afk"

-- The block flavor of a Rex terminal.
local TERMINAL = "com.superlogical.terminal.shell"

local function say(text)
  rex.log("afk: " .. text)
end

local function failed(what, err)
  say("could not " .. what .. " on the Rex host \"" .. HUB .. "\": " .. tostring(err))
end

-- hub_call makes one call to the hub and returns its reply, or nil and the
-- reason. rex.server throws for a host this device does not know, and a call
-- that fails returns nil and an error, so both end up here as nil and text.
local function hub_call(method, args)
  local ok, server = pcall(rex.server, HUB)
  if not ok then
    return nil, tostring(server)
  end
  local called, reply, err = pcall(server.call, method, args)
  if not called then
    return nil, tostring(reply)
  end
  if reply == nil then
    return nil, tostring(err or "the hub did not answer")
  end
  return reply
end

-- session_call makes a call about one session. Over this connection the hub
-- refuses those (session.list_blocks, block.method, session.focus_window,
-- session.new_window) with "stream is not attached to session" until the
-- connection attaches to the session.
-- So the call is tried as it is first, and only on that refusal does this
-- attach, try again and detach. A session this connection was already
-- attached to (the laptop may share its own connection) is never detached.
local function session_call(session_id, method, args)
  local reply, err = hub_call(method, args)
  if reply or not string.find(tostring(err), "not attached", 1, true) then
    return reply, err
  end
  local _, attach_err = hub_call("session.attach", {session_id = session_id})
  if attach_err then
    return nil, attach_err
  end
  reply, err = hub_call(method, args)
  hub_call("session.detach", {session_id = session_id})
  return reply, err
end

-- list returns reply[field] when it is a list, else an empty one: Rex can
-- send null for an empty list, and a failed call has no reply at all.
local function list(reply, field)
  if type(reply) == "table" and type(reply[field]) == "table" then
    return reply[field]
  end
  return {}
end

-- window_of returns the window a block is shown in, or nil for a block no
-- window shows (Rex counts any placement other than "placed" as detached).
local function window_of(block)
  if block.placement == "placed" and type(block.window_id) == "string" and block.window_id ~= "" then
    return block.window_id
  end
  return nil
end

-- control_room_session returns the id of the hub's "afk" session.
local function control_room_session()
  local reply, err = hub_call("session.list", {})
  if not reply then
    return nil, err
  end
  for _, s in ipairs(list(reply, "sessions")) do
    if s.label == CONTROL_ROOM and type(s.session_id) == "string" then
      return s.session_id
    end
  end
  return nil, "it has no Rex session named \"" .. CONTROL_ROOM .. "\"; is the afk daemon running there with the Rex backend?"
end

-- control_room_window returns the control room's window: the window of the
-- block labelled "afk", else any open window of the session (a pause or
-- resume terminal can be open beside it for a moment).
local function control_room_window(session_id)
  local reply, err = session_call(session_id, "session.list_blocks", {session_id = session_id})
  if not reply then
    return nil, err
  end
  local any
  for _, b in ipairs(list(reply, "blocks")) do
    local w = window_of(b)
    if w and b.label == CONTROL_ROOM then
      return w
    end
    any = any or w
  end
  if any then
    return any
  end
  return nil, "the \"" .. CONTROL_ROOM .. "\" session has no open window; the afk daemon opens it again within a minute"
end

-- focus brings a window forward. Rex does this for the whole session: every
-- client looking at that session switches to the window.
local function focus(session_id, window_id)
  local _, err = session_call(session_id, "session.focus_window", {session_id = session_id, window_id = window_id})
  return err
end

-- needing_you walks the hub's sessions in order and each shown block's
-- program status, and returns the first blocked record, else the first
-- error, with the session and window it is in. A session or block that does
-- not answer (it closed, or it is not a terminal) is skipped.
local function needing_you()
  local reply, err = hub_call("session.list", {})
  if not reply then
    return nil, err
  end
  local first_error
  for _, s in ipairs(list(reply, "sessions")) do
    if type(s.session_id) == "string" then
      local blocks = session_call(s.session_id, "session.list_blocks", {session_id = s.session_id})
      for _, b in ipairs(list(blocks, "blocks")) do
        local w = window_of(b)
        if w and type(b.block_id) == "string" then
          local status = session_call(s.session_id, "block.method", {session_id = s.session_id, block_id = b.block_id, method = "program_status"})
          for _, r in ipairs(list(status, "records")) do
            local found = {session_id = s.session_id, window_id = w, session = tostring(s.label or s.session_id), msg = r.msg}
            if r.state == "blocked" then
              return found
            end
            if r.state == "error" and not first_error then
              first_error = found
            end
          end
        end
      end
    end
  end
  return first_error
end

-- run_on_hub opens a terminal in a new window of the "afk" session that runs
-- ` + "`afk WORD`" + ` and closes when the program ends. The command goes through
-- the hub user's shell, which reads its startup files, so afk is found on the
-- PATH they set. A command that fails at once leaves the window open so the
-- error can be read; the window is focused so it is seen.
local function run_on_hub(word)
  local what = word .. " the build"
  local session_id, err = control_room_session()
  if not session_id then
    return failed(what, err)
  end
  local label = "afk " .. word
  local _, err2 = session_call(session_id, "session.new_window", {
    session_id = session_id,
    window_label = label,
    focus = true,
    layout = {block = {
      flavor = TERMINAL,
      label = label,
      options = {
        command = {"afk", word},
        exit = {on_completion = true, quick_exit_threshold_ms = 250},
      },
    }},
  })
  if err2 then
    return failed(what, err2)
  end
  say("asked the Rex host \"" .. HUB .. "\" to " .. what)
end

rex.action{
  name = "afk_control_room",
  title = "afk: Open the control room",
  category = "afk",
  description = "Bring the afk dashboard on the hub forward.",
  run = function()
    local session_id, err = control_room_session()
    if not session_id then
      return failed("open the control room", err)
    end
    local window_id, err2 = control_room_window(session_id)
    if not window_id then
      return failed("open the control room", err2)
    end
    local err3 = focus(session_id, window_id)
    if err3 then
      return failed("open the control room", err3)
    end
  end,
}

rex.action{
  name = "afk_next_needs_you",
  title = "afk: Go to the next agent that needs you",
  category = "afk",
  description = "Bring forward the first agent on the hub that is waiting on you, else the first that stopped with an error.",
  run = function()
    local found, err = needing_you()
    if err then
      return failed("look for an agent that needs you", err)
    end
    if not found then
      return say("no agent on the Rex host \"" .. HUB .. "\" needs you right now")
    end
    local err2 = focus(found.session_id, found.window_id)
    if err2 then
      return failed("bring forward the agent in " .. found.session, err2)
    end
    if type(found.msg) == "string" and found.msg ~= "" then
      say(found.session .. ": " .. found.msg)
    end
  end,
}

rex.action{
  name = "afk_pause",
  title = "afk: Pause the build",
  category = "afk",
  description = "Run afk pause on the hub, in a terminal that closes when it is done.",
  run = function()
    run_on_hub("pause")
  end,
}

rex.action{
  name = "afk_resume",
  title = "afk: Resume the build",
  category = "afk",
  description = "Run afk resume on the hub, in a terminal that closes when it is done.",
  run = function()
    run_on_hub("resume")
  end,
}
`
